def transform(grid):
    """Sort the five two-column strips by their foreground-cell count (ascending)."""
    h, w = len(grid), len(grid[0])
    starts = [0, 3, 6, 9, 12]
    strips = [[ [grid[r][c] for r in range(h)] for c in (s, s + 1) ] for s in starts]
    order = sorted(range(5), key=lambda k: sum(v != 0 for col in strips[k] for v in col))
    out = [[0] * w for _ in range(h)]
    for j, k in enumerate(order):
        s = starts[j]
        for d in range(2):
            for r in range(h):
                out[r][s + d] = strips[k][d][r]
    return out
